<?php
namespace App\Http\Controllers\Crm;
use App\Http\Controllers\Controller; use App\Models\{Client,Invoice,Lead,LeadFollowup,Payment}; use Illuminate\View\View;
class CrmDashboardController extends Controller { public function __invoke():View{$total=Lead::count();$won=Lead::whereIn('status',['won','converted'])->count();return view('crm.dashboard',[ 'stats'=>['Total Leads'=>$total,'New Leads'=>Lead::where('status','new')->count(),'Qualified Leads'=>Lead::where('status','qualified')->count(),'Won Leads'=>$won,'Total Clients'=>Client::count(),'Pending Follow-ups'=>LeadFollowup::where('status','pending')->count(),'Overdue Follow-ups'=>LeadFollowup::where('status','pending')->whereDate('follow_up_date','<',today())->count(),'Outstanding Payments'=>Invoice::sum('total')-Payment::sum('amount')], 'pipeline'=>Lead::selectRaw('stage,count(*) as total')->groupBy('stage')->pluck('total','stage'), 'sources'=>Lead::selectRaw('source,count(*) as total')->groupBy('source')->pluck('total','source'), 'conversion'=>$total?round($won/$total*100,1):0]);}}
